import copy, json, sys, time
from pathlib import Path
import boto3
from botocore.config import Config
from botocore.exceptions import ClientError

ROOT = Path('/home/r/dev/minor/stackd-ec2-public-network')
STATE = Path('/tmp/stackd-public-review-iam-state.json')
RESULTS = Path('/tmp/stackd-public-review-iam-results.json')
MODE = sys.argv[1]
fixture = json.loads((ROOT / 'testdata/aws/ec2/public_addresses_iam_federation.json').read_text())

def client(service, credentials=None):
    credentials = credentials or {'AccessKeyId': fixture['account'], 'SecretAccessKey': 'test', 'SessionToken': ''}
    return boto3.client(service, endpoint_url='http://127.0.0.1:4579', region_name=fixture['region'], aws_access_key_id=credentials['AccessKeyId'], aws_secret_access_key=credentials['SecretAccessKey'], aws_session_token=credentials.get('SessionToken'), config=Config(retries={'max_attempts': 0}))

ec2, iam = client('ec2'), client('iam')
if MODE == 'before':
    state = {'sessions': {}, 'owned': {}}
    def save(): STATE.write_text(json.dumps(state, default=str))
    direct = client('ebs')
    state['owned']['snapshot'] = direct.start_snapshot(VolumeSize=1)['SnapshotId']; save()
    direct.complete_snapshot(SnapshotId=state['owned']['snapshot'], ChangedBlocksCount=0)
    time.sleep(6.2)
    state['owned']['image'] = ec2.register_image(Name='public-ip-review-dry-run', Architecture='x86_64', VirtualizationType='hvm', RootDeviceName='/dev/sda1', BlockDeviceMappings=[{'DeviceName': '/dev/sda1', 'Ebs': {'SnapshotId': state['owned']['snapshot'], 'VolumeSize': 1, 'VolumeType': 'gp3', 'DeleteOnTermination': True}}])['ImageId']; save()
    state['owned']['vpc'] = ec2.create_vpc(CidrBlock='10.235.0.0/24')['Vpc']['VpcId']; save()
    state['owned']['subnet'] = ec2.create_subnet(VpcId=state['owned']['vpc'], CidrBlock='10.235.0.0/25')['Subnet']['SubnetId']; save()
    address = ec2.allocate_address()
    state['owned']['allocation'] = address['AllocationId']; state['owned']['public'] = address['PublicIp']; save()
    state['owned']['user'] = 'PublicIPv4NativeReview'
    iam.create_user(UserName=state['owned']['user']); save()
    iam.put_user_policy(UserName=state['owned']['user'], PolicyName='review', PolicyDocument=json.dumps({'Statement': {'Effect': 'Allow', 'Action': ['ec2:*', 'sts:GetFederationToken'], 'Resource': '*'}}))
    state['user_credentials'] = iam.create_access_key(UserName=state['owned']['user'])['AccessKey']; save()
else:
    state = json.loads(STATE.read_text())

results = json.loads(RESULTS.read_text()) if RESULTS.exists() else {}
if MODE == 'cleanup':
    owned = state['owned']; operations = []
    ec2.release_address(AllocationId=owned['allocation']); operations.append('release exact EIP')
    ec2.deregister_image(ImageId=owned['image']); operations.append('deregister exact image')
    ec2.delete_snapshot(SnapshotId=owned['snapshot']); operations.append('delete exact snapshot')
    ec2.delete_subnet(SubnetId=owned['subnet']); ec2.delete_vpc(VpcId=owned['vpc']); operations.append('delete exact subnet and VPC')
    iam.delete_user_policy(UserName=owned['user'], PolicyName='review')
    iam.delete_access_key(UserName=owned['user'], AccessKeyId=state['user_credentials']['AccessKeyId'])
    iam.delete_user(UserName=owned['user']); operations.append('delete exact IAM policy, key and user')
    for method, kwargs, code in [(ec2.describe_addresses, {'AllocationIds': [owned['allocation']]}, 'InvalidAllocationID.NotFound'), (ec2.describe_subnets, {'SubnetIds': [owned['subnet']]}, 'InvalidSubnetID.NotFound'), (ec2.describe_vpcs, {'VpcIds': [owned['vpc']]}, 'InvalidVpcID.NotFound'), (iam.get_user, {'UserName': owned['user']}, 'NoSuchEntity')]:
        try: method(**kwargs)
        except ClientError as error: assert error.response['Error']['Code'] == code, error
        else: raise AssertionError('owned resource survived deletion')
    results['cleanup'] = {'operations': operations, 'absence_confirmed': True}
    RESULTS.write_text(json.dumps(results, indent=2)); STATE.unlink()
    print(json.dumps(results['cleanup'])); sys.exit(0)

bindings = {fixture['owned']['allocation_id']: state['owned']['allocation'], fixture['owned']['public_ip']: state['owned']['public'], fixture['owned']['subnet_id']: state['owned']['subnet']}
for row in fixture['calls']:
    if row['operation'] == 'RunInstances': bindings[row['input']['ImageId']] = state['owned']['image']
def bind(value):
    if isinstance(value, str):
        for old, new in bindings.items(): value = value.replace(old, new)
        return value
    if isinstance(value, dict): return {k: bind(v) for k, v in value.items()}
    if isinstance(value, list): return [bind(v) for v in value]
    return value
observations = []
for row in fixture['calls']:
    operation, args = row['operation'], bind(copy.deepcopy(row['input']))
    if operation == 'GetFederationToken':
        if MODE == 'before':
            state['sessions'][args['Name']] = client('sts', state['user_credentials']).get_federation_token(**args)['Credentials']
            STATE.write_text(json.dumps(state, default=str))
    elif operation == 'ModifySubnetAttribute': ec2.modify_subnet_attribute(**args)
    elif operation in ('RunInstances', 'ReleaseAddress') and args.get('DryRun'):
        sdk = client('ec2', state['sessions'][row['caller']])
        method = sdk.run_instances if operation == 'RunInstances' else sdk.release_address
        try: method(**args); code = 'Success'; request_id = None
        except ClientError as error:
            code = error.response['Error']['Code']; request_id = error.response['ResponseMetadata']['RequestId']
        observations.append({'label': row['label'], 'operation': operation, 'expected_native_code': row['code'], 'actual_code': code, 'request_id': request_id})
assert not ec2.describe_instances()['Reservations']
assert not ec2.describe_network_interfaces()['NetworkInterfaces']
assert not ec2.describe_volumes()['Volumes']
mismatches = [row for row in observations if row['expected_native_code'] != row['actual_code']]
results[MODE] = {'observations': observations, 'mismatches': mismatches, 'dry_run_created_no_compute_resources': True, 'retained_sessions_reused_after_controller_reopen': MODE == 'after'}
RESULTS.write_text(json.dumps(results, indent=2))
print(json.dumps({'mode': MODE, 'observations': len(observations), 'mismatches': mismatches}, indent=2))
if MODE == 'before':
    assert {row['label'] for row in mismatches} == {f'subnet-{subnet}-request-{request}-{condition}' for subnet in ('false', 'true') for request, condition in (('false', 'BoolIfExists'), ('true', 'Bool'))}
else: assert not mismatches
